import Image from "next/image"

import { cn } from "@/intranet/lib/utils"

/**
 * JDH brand logo. Variants map to the four source marks (see `public/logos/`,
 * generated by `scripts/generate-brand-assets.mjs`):
 *   full = logotype general · text = wordmark only · mark = isotype ·
 *   compact = mark + partial name.
 * Plus `lockup`: mark + wordmark composed at render time (sharper than the
 * baked `compact` asset, since each part is scaled from its own source).
 *
 * `tone`: `white`/`black` pick the fixed asset; `auto` swaps by theme purely
 * with the `dark:` CSS variant (no state, no hydration mismatch — the hidden
 * variant is display:none, so screen readers only announce the visible one).
 * `auto-inverse` is the same swap reversed (white in light, black in dark) —
 * for surfaces that invert against the theme, e.g. the footer.
 * RSC-safe.
 */
const RATIOS = {
  full: 2.626,
  text: 4.688,
  mark: 1,
  compact: 2.626,
} as const

export type LogoVariant = keyof typeof RATIOS
export type LogoTone = "white" | "black" | "auto" | "auto-inverse"

/** Wordmark height and gap, as a fraction of the lockup's height. */
const LOCKUP_TEXT_SCALE = 0.6
const LOCKUP_GAP_SCALE = 0.3

export interface LogoProps {
  variant?: LogoVariant | "lockup"
  tone?: LogoTone
  /** Rendered height in px; width is derived from the variant's aspect ratio. */
  height?: number
  priority?: boolean
  className?: string
  alt?: string
}

function LogoImage({
  variant,
  tone,
  height,
  priority,
  className,
  alt,
}: {
  variant: LogoVariant
  tone: LogoTone
  height: number
  priority?: boolean
  className?: string
  alt: string
}) {
  const width = Math.round(height * RATIOS[variant])
  const common = { width, height, priority }

  if (tone === "auto" || tone === "auto-inverse") {
    const inLight = tone === "auto" ? "black" : "white"
    const inDark = tone === "auto" ? "white" : "black"

    return (
      <>
        <Image
          src={`/logos/${variant}-${inLight}.png`}
          alt={alt}
          {...common}
          className={cn("dark:hidden", className)}
        />
        <Image
          src={`/logos/${variant}-${inDark}.png`}
          alt={alt}
          {...common}
          className={cn("hidden dark:block", className)}
        />
      </>
    )
  }

  return (
    <Image
      src={`/logos/${variant}-${tone}.png`}
      alt={alt}
      {...common}
      className={className}
    />
  )
}

export function Logo({
  variant = "full",
  tone = "black",
  height = 32,
  priority,
  className,
  alt = "Juan D. Hoyos Distribuciones",
}: LogoProps) {
  if (variant === "lockup") {
    return (
      <span
        className={cn("inline-flex items-center", className)}
        // Gap proporcional a la altura: es layout estructural derivado de una
        // prop, no estilo — misma excepción documentada que `gridTemplate` en
        // DataTable.
        style={{ gap: Math.round(height * LOCKUP_GAP_SCALE) }}
      >
        {/* El isotipo es decorativo: el nombre accesible lo aporta el wordmark. */}
        <LogoImage
          variant="mark"
          tone={tone}
          height={height}
          priority={priority}
          alt=""
        />
        <LogoImage
          variant="text"
          tone={tone}
          height={Math.round(height * LOCKUP_TEXT_SCALE)}
          priority={priority}
          alt={alt}
        />
      </span>
    )
  }

  return (
    <LogoImage
      variant={variant}
      tone={tone}
      height={height}
      priority={priority}
      className={className}
      alt={alt}
    />
  )
}
